def _fill_from_raw_payloads() -> None:
    """Activities already synced keep the source's full answer in raw_payload:
    read the town and the start point from it, so no re-sync is needed."""
    bind = op.get_bind()
    rows = bind.execute(
        sa.text("SELECT source, external_id, payload FROM raw_payload WHERE kind = 'activity'")
    )
    for source, external_id, payload in rows.fetchall():
        values = _location(source, payload)
        if values is None:
            continue
        bind.execute(
            sa.text(
                "UPDATE activity SET location_name = :name, start_latitude = :lat, "
                "start_longitude = :lng WHERE source = :source AND external_id = :external_id"
            ),
            {**values, "source": source, "external_id": external_id},
        )


def _location(source: str, payload: Any) -> dict[str, Any] | None:
    if isinstance(payload, str):  # raw SQL may return the JSON as text
        payload = json.loads(payload)
    if not isinstance(payload, dict):
        return None
    if source == "garmin":
        name, lat, lng = (
            payload.get("locationName"),
            payload.get("startLatitude"),
            payload.get("startLongitude"),
        )
    elif source == "strava":
        latlng = payload.get("start_latlng") or [None, None]
        name = payload.get("location_city")
        lat, lng = (latlng + [None, None])[:2]
    else:
        return None
    if not _number(lat) or not _number(lng):
        lat = lng = None
    name = name[:120] if isinstance(name, str) and name else None
    if name is None and lat is None:
        return None
    return {"name": name, "lat": lat, "lng": lng}


def _number(value: Any) -> bool:
    return isinstance(value, int | float) and not isinstance(value, bool)


